const updateVendor = `-- name: UpdateVendor :one
UPDATE vendors SET name = $2, is_active = $3 WHERE id = $1 RETURNING id, slug, name, is_active, created_at, updated_at
`

type UpdateVendorParams struct {
	ID       uuid.UUID `json:"id"`
	Name     string    `json:"name"`
	IsActive bool      `json:"is_active"`
}

func (q *Queries) UpdateVendor(ctx context.Context, arg UpdateVendorParams) (Vendor, error) {
	row := q.db.QueryRow(ctx, updateVendor, arg.ID, arg.Name, arg.IsActive)
	var i Vendor
	err := row.Scan(
		&i.ID,
		&i.Slug,
		&i.Name,
		&i.IsActive,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
